#include<cstddef>
#include<string>
#include<array>
#include<fstream>

std::array<std::string,6> gen_ook(std::string const& str){
    std::array<std::string,6> ret={}; 
    for(char ch:str){
        if(ch=='.'){
            ret[0].append("Ook.");
            ret[1].append("Ook.");
            ret[2].append("Ook!");
            ret[3].append("Ook!");
            ret[4].append("Ook?");
            ret[5].append("Ook?");
        }else if(ch=='-'){
            ret[0].append("Ook!");
            ret[1].append("Ook?");
            ret[2].append("Ook.");
            ret[3].append("Ook?");
            ret[4].append("Ook.");
            ret[5].append("Ook!");
        }else{
            ret[0].append("Ook?");
            ret[1].append("Ook!");
            ret[2].append("Ook?");
            ret[3].append("Ook.");
            ret[4].append("Ook!");
            ret[5].append("Ook.");
        }
    }
    return ret;
}

